text:
{
  "title_novice": "Наступление и отступание моря в разрезе",
  "summary": [
    {"text": "Мощные разрезы дельт в основном сложены терригенными породами, то есть обломочными породами.", "claims": ["c1"]},
    {"text": "В одном таком разрезе могут быть и трансгрессивная, и регрессивная последовательность фаций.", "claims": ["c3"]}
  ],
  "claims": [
    {"key": "c1", "text": "Разрезы дельт мощные и в основном терригенные.", "kind": "observation", "unit_id": "u-031-e5b4d1", "page": 31, "quote": "Мощные, преимущественно терригенные разрезы как с трансгрессивной, так и с регрессивной последовательностью фаций.", "numbers": [], "question": null},
    {"key": "c2", "text": "Автор называет мощные терригенные разрезы одной из общих черт дельт.", "kind": "observation", "unit_id": "u-031-8383ee", "page": 31, "quote": "Дельтам присущи следующие общие черты:", "numbers": [], "question": null},
    {"key": "c3", "text": "В разрезе дельты встречаются и трансгрессивная, и регрессивная последовательность фаций.", "kind": "observation", "unit_id": "u-031-e5b4d1", "page": 31, "quote": "как с трансгрессивной, так и с регрессивной последовательностью фаций", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Разрез дельты — это стопка слоёв. Нижние слои отложились раньше верхних.", "claims": [], "hypothesis": true},
    {"text": "Граница суши и моря — линия, где берег встречается с водой. Она может сдвигаться.", "claims": [], "hypothesis": true},
    {"text": "Если граница сдвигается к морю, на мелкие слои ложатся более крупные. Так возникает регрессивный порядок.", "claims": [], "hypothesis": true},
    {"text": "Если море наступает на дельту, на крупные слои ложатся более мелкие, глинистые. Так возникает трансгрессивный порядок.", "claims": [], "hypothesis": true},
    {"text": "Автор отмечает: мощные разрезы дельт в основном терригенные и содержат оба порядка фаций.", "claims": ["c1", "c3"], "hypothesis": false},
    {"text": "Мощность появляется, когда осадок накапливается долго, слой за слоем.", "claims": [], "hypothesis": true}
  ],
  "practice": [
    {"text": "Смотрите, как меняется размер зёрен от подошвы разреза к кровле.", "claims": [], "hypothesis": true},
    {"text": "Если зёрна крупнее вверх, это признак регрессивной последовательности.", "claims": [], "hypothesis": true},
    {"text": "Если зёрна мельче вверх, это признак трансгрессивной последовательности.", "claims": [], "hypothesis": true},
    {"text": "Сравнивайте соседние разрезы, чтобы понять, какой порядок преобладает в теле дельты.", "claims": [], "hypothesis": true}
  ],
  "nuances": [
    {"text": "Слово «общие» означает, что такие черты типичны для дельт. Они не обязательны для каждой дельты.", "claims": ["c2"]},
    {"text": "В тексте не назван порог мощности. Слово «мощные» относительное, в метрах его не измеряли.", "claims": ["c1"]},
    {"text": "Текст не говорит, какая последовательность преобладает в конкретной дельте. Для этого нужны сами разрезы.", "claims": ["c3"]},
    {"text": "Одна и та же смена пород может возникнуть и без движения моря. Поэтому порядок нужно проверять по другим признакам.", "claims": [], "hypothesis": true}
  ],
  "deeper": [
    {"title": "Почему порядок пород читается как история", "text": "Вертикальный порядок пород можно читать как запись сдвигов границы моря. Это удобная модель, а не точное правило: разрез могут переработать волны или реки.", "claims": [], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Числа мощности в тексте нет: разрез назван мощным, но в метрах не измерен.", "claims": ["c1"]},
    {"text": "Условие: разрез состоит преимущественно из терригенных пород.", "claims": ["c1"]},
    {"text": "Условие: в одном разрезе могут присутствовать и трансгрессивная, и регрессивная последовательность фаций.", "claims": ["c3"]}
  ],
  "terms_defined": [
    {"term": "терригенные породы", "term_en": "terrigenous rocks", "abbr": "", "definition": "Обломочные породы, сложенные частицами, которые принесены с суши водой, ветром или льдом.", "claims": []},
    {"term": "трансгрессия", "term_en": "transgression", "abbr": "", "definition": "Наступление моря на сушу: граница суши и моря смещается к берегу.", "claims": []},
    {"term": "регрессия", "term_en": "regression", "abbr": "", "definition": "Отступание моря от суши: граница суши и моря смещается в сторону моря.", "claims": []},
    {"term": "трансгрессивная последовательность", "term_en": "transgressive sequence", "abbr": "", "definition": "Порядок фаций вверх по разрезу, когда мелководные фации сменяются более глубоководными и мельче по зерну.", "claims": []},
    {"term": "регрессивная последовательность", "term_en": "regressive sequence", "abbr": "", "definition": "Порядок фаций вверх по разрезу, когда глубоководные фации сменяются мелководными и крупнее по зерну.", "claims": []}
  ],
  "terms_used": ["дельта", "фация"],
  "formulas": [],
  "tables": [],
  "figures": [],
  "worked_examples": [],
  "book_problems": [],
  "misconception": {
    "pack_id": null,
    "wrong": "Разрез дельты — случайная толща песка и глины. Порядок пород по вертикали ничего не значит.",
    "right": "Разрез дельты обычно мощный и терригенный. В нём может быть трансгрессивная или регрессивная последовательность фаций.",
    "claims": ["c1", "c3"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Вертикальная запись пород по керну или обнажению: состав и размер зёрен по глубине.", "claims": [], "hypothesis": true}
    ],
    "outputs": [
      {"text": "Тип порядка фаций: трансгрессивный, регрессивный или смешанный.", "claims": [], "hypothesis": true}
    ],
    "breaks": [
      {"text": "Порог мощности в тексте не задан, поэтому «мощный» разрез нужно сравнивать с соседними разрезами.", "claims": ["c1"], "hypothesis": false},
      {"text": "Одинаковая смена зернистости может возникнуть и по другим причинам, не только из-за моря.", "claims": [], "hypothesis": true}
    ]
  },
  "it_analogy": {
    "pack_id": null,
    "analogy": "Журнал событий, записанный по времени: более ранние записи лежат глубже. Порядок записей показывает, что было раньше.",
    "breaks_where": "Журнал пишется без пропусков. Слои могут быть размыты или переработаны, и порядок тогда неполный.",
    "hypothesis": true
  },
  "now_nuance": null,
  "threshold": {
    "is_threshold": true,
    "why": "Без понимания, что порядок пород отражает сдвиг границы суши и моря, разрез дельты читается как случайная смесь."
  },
  "inefficiency": {
    "inputs": ["Описания разрезов из керна и обнажений: состав и размер зёрен по глубине (гипотеза)."],
    "manual_steps": ["Сопоставить порядок пород по вертикали с описанием разреза (гипотеза)."],
    "judgment_points": ["Решить, трансгрессивная или регрессивная последовательность перед нами (гипотеза)."],
    "time": ["Сравнивать несколько разрезов, чтобы понять общий тип дельты (гипотеза)."],
    "typical_errors": ["Принять одну смену пород за общий тип всей дельты (гипотеза)."]
  },
